-- MATHEMATICS Problem of the Day (20 questions)
('nsmq_math_pod_001', 'subj_math', 'A train travels from town A to town B at 60 km/h and returns at 40 km/h. If the total journey takes 5 hours, what is the distance between A and B?', 'problem', 'problem_of_day', NULL, '120 km', 'Let distance = d. Time = d/60 + d/40 = 5. Solving: d(40+60)/2400 = 5, d = 120 km', 'hard', 5, 120),
('nsmq_math_pod_002', 'subj_math', 'The sum of three consecutive even numbers is 78. Find the largest number.', 'problem', 'problem_of_day', NULL, '28', 'Let numbers be n, n+2, n+4. Sum: 3n + 6 = 78, n = 24. Largest = 28', 'medium', 5, 120),
('nsmq_math_pod_003', 'subj_math', 'A ladder 10 m long rests against a wall. If the base is 6 m from the wall, how high up the wall does the ladder reach?', 'problem', 'problem_of_day', NULL, '8 m', 'Using Pythagoras: h² + 6² = 10², h² = 64, h = 8 m', 'medium', 5, 120),
('nsmq_math_pod_004', 'subj_math', 'Find the sum of the first 15 terms of the arithmetic progression: 3, 7, 11, 15, ...', 'problem', 'problem_of_day', NULL, '465', 'a=3, d=4, n=15. S₁₅ = 15/2[2(3) + 14(4)] = 15/2 × 62 = 465', 'hard', 5, 120),
('nsmq_math_pod_005', 'subj_math', 'If 2^(x+1) = 32, find the value of x.', 'problem', 'problem_of_day', NULL, '4', '2^(x+1) = 2⁵, so x+1 = 5, x = 4', 'medium', 5, 120),
('nsmq_math_pod_006', 'subj_math', 'A cylindrical tank has radius 7 cm and height 10 cm. What is its volume? (Use π = 22/7)', 'problem', 'problem_of_day', NULL, '1540 cm³', 'V = πr²h = (22/7) × 49 × 10 = 1540 cm³', 'medium', 5, 120),
('nsmq_math_pod_007', 'subj_math', 'Solve the simultaneous equations: 2x + 3y = 12 and x - y = 1', 'problem', 'problem_of_day', NULL, 'x = 3, y = 2', 'From equation 2: x = y + 1. Substituting: 2(y+1) + 3y = 12, 5y = 10, y = 2, x = 3', 'medium', 5, 120),
('nsmq_math_pod_008', 'subj_math', 'A bag contains 5 red balls and 3 blue balls. If two balls are drawn without replacement, what is the probability that both are red?', 'problem', 'problem_of_day', NULL, '5/14', 'P = (5/8) × (4/7) = 20/56 = 5/14', 'hard', 5, 120),
('nsmq_math_pod_009', 'subj_math', 'Find the compound interest on GH₵2000 at 10% per annum for 2 years, compounded annually.', 'problem', 'problem_of_day', NULL, 'GH₵420', 'A = 2000(1.1)² = 2420. CI = 2420 - 2000 = GH₵420', 'hard', 5, 120),
('nsmq_math_pod_010', 'subj_math', 'The angles of a triangle are in the ratio 2:3:4. Find the largest angle.', 'problem', 'problem_of_day', NULL, '80°', 'Total = 180°. Parts: 2x + 3x + 4x = 180, 9x = 180, x = 20. Largest = 4(20) = 80°', 'medium', 5, 120),
('nsmq_math_pod_011', 'subj_math', 'If the roots of x² - 5x + k = 0 are equal, find k.', 'problem', 'problem_of_day', NULL, '25/4', 'For equal roots: b² - 4ac = 0. 25 - 4k = 0, k = 25/4', 'hard', 5, 120),
('nsmq_math_pod_012', 'subj_math', 'A man is 4 times as old as his son. In 20 years, he will be twice as old as his son. How old is the son now?', 'problem', 'problem_of_day', NULL, '10 years', 'Let son = x, man = 4x. 4x + 20 = 2(x + 20), 4x + 20 = 2x + 40, x = 10', 'hard', 5, 120),
('nsmq_math_pod_013', 'subj_math', 'Find the equation of the line passing through (2, 3) and (4, 7).', 'problem', 'problem_of_day', NULL, 'y = 2x - 1', 'Gradient m = (7-3)/(4-2) = 2. y - 3 = 2(x - 2), y = 2x - 1', 'medium', 5, 120),
('nsmq_math_pod_014', 'subj_math', 'Evaluate: ∫(3x² + 2x) dx from x = 0 to x = 2', 'problem', 'problem_of_day', NULL, '12', '∫(3x² + 2x)dx = x³ + x². At x=2: 8 + 4 = 12. At x=0: 0. Answer = 12', 'hard', 5, 120),
('nsmq_math_pod_015', 'subj_math', 'A cone has base radius 3 cm and height 4 cm. What is its slant height?', 'problem', 'problem_of_day', NULL, '5 cm', 'l² = r² + h² = 9 + 16 = 25, l = 5 cm', 'medium', 5, 120),
('nsmq_math_pod_016', 'subj_math', 'Simplify: (√5 + √3)(√5 - √3)', 'problem', 'problem_of_day', NULL, '2', 'Using difference of squares: (√5)² - (√3)² = 5 - 3 = 2', 'medium', 5, 120),
('nsmq_math_pod_017', 'subj_math', 'The mean of 5 numbers is 12. If one number is removed, the mean becomes 10. What number was removed?', 'problem', 'problem_of_day', NULL, '20', 'Sum of 5 = 60. Sum of 4 = 40. Removed = 60 - 40 = 20', 'medium', 5, 120),
('nsmq_math_pod_018', 'subj_math', 'Find the value of x if log₂(x) + log₂(x-2) = 3', 'problem', 'problem_of_day', NULL, '4', 'log₂[x(x-2)] = 3, x² - 2x = 8, x² - 2x - 8 = 0, (x-4)(x+2) = 0, x = 4', 'hard', 5, 120),
('nsmq_math_pod_019', 'subj_math', 'A sector of a circle has radius 14 cm and angle 90°. Find its area. (Use π = 22/7)', 'problem', 'problem_of_day', NULL, '154 cm²', 'Area = (θ/360) × πr² = (90/360) × (22/7) × 196 = 154 cm²', 'medium', 5, 120),
('nsmq_math_pod_020', 'subj_math', 'How many ways can 5 students be arranged in a row?', 'problem', 'problem_of_day', NULL, '120', 'Number of arrangements = 5! = 120', 'medium', 5, 120),

-- PHYSICS Problem of the Day (20 questions)
('nsmq_phy_pod_001', 'subj_physics', 'A car accelerates from rest at 2 m/s² for 10 seconds. What distance does it cover?', 'problem', 'problem_of_day', NULL, '100 m', 's = ut + ½at² = 0 + ½(2)(100) = 100 m', 'medium', 5, 120),
('nsmq_phy_pod_002', 'subj_physics', 'A 5 kg mass is lifted 10 m high. How much potential energy does it gain? (g = 10 m/s²)', 'problem', 'problem_of_day', NULL, '500 J', 'PE = mgh = 5 × 10 × 10 = 500 J', 'medium', 5, 120),
('nsmq_phy_pod_003', 'subj_physics', 'A 100W bulb is used for 5 hours. How much energy is consumed in kWh?', 'problem', 'problem_of_day', NULL, '0.5 kWh', 'Energy = Power × Time = 0.1 kW × 5 h = 0.5 kWh', 'medium', 5, 120),
('nsmq_phy_pod_004', 'subj_physics', 'A wave has frequency 50 Hz and wavelength 2 m. What is its speed?', 'problem', 'problem_of_day', NULL, '100 m/s', 'v = fλ = 50 × 2 = 100 m/s', 'easy', 5, 120),
('nsmq_phy_pod_005', 'subj_physics', 'Two resistors of 6Ω each are connected in series. What is the total resistance?', 'problem', 'problem_of_day', NULL, '12Ω', 'In series: R_total = R₁ + R₂ = 6 + 6 = 12Ω', 'easy', 5, 120),
('nsmq_phy_pod_006', 'subj_physics', 'A ball is thrown vertically upward at 20 m/s. What maximum height does it reach? (g = 10 m/s²)', 'problem', 'problem_of_day', NULL, '20 m', 'At max height, v = 0. v² = u² - 2gh, 0 = 400 - 20h, h = 20 m', 'medium', 5, 120),
('nsmq_phy_pod_007', 'subj_physics', 'If a current of 2A flows through a 10Ω resistor, what is the power dissipated?', 'problem', 'problem_of_day', NULL, '40 W', 'P = I²R = 4 × 10 = 40 W', 'medium', 5, 120),
('nsmq_phy_pod_008', 'subj_physics', 'A concave mirror has focal length 20 cm. An object is placed 30 cm from it. Where is the image formed?', 'problem', 'problem_of_day', NULL, '60 cm', '1/f = 1/v + 1/u. 1/20 = 1/v + 1/30. 1/v = 1/20 - 1/30 = 1/60, v = 60 cm', 'hard', 5, 120),
('nsmq_phy_pod_009', 'subj_physics', 'A 2 kg ball moving at 5 m/s collides with a wall and bounces back at 3 m/s. What is the change in momentum?', 'problem', 'problem_of_day', NULL, '16 kg⋅m/s', 'Change = m(v - u) = 2((-3) - 5) = 2 × (-8) = -16 kg⋅m/s. Magnitude = 16 kg⋅m/s', 'hard', 5, 120),
('nsmq_phy_pod_010', 'subj_physics', 'A transformer has 100 turns in the primary and 500 in the secondary. If the input voltage is 220V, what is the output?', 'problem', 'problem_of_day', NULL, '1100 V', 'V₂/V₁ = N₂/N₁. V₂ = 220 × 500/100 = 1100 V', 'medium', 5, 120),
('nsmq_phy_pod_011', 'subj_physics', 'What is the kinetic energy of a 4 kg object moving at 10 m/s?', 'problem', 'problem_of_day', NULL, '200 J', 'KE = ½mv² = ½ × 4 × 100 = 200 J', 'easy', 5, 120),
('nsmq_phy_pod_012', 'subj_physics', 'A block of mass 2 kg experiences a net force of 8 N. What is its acceleration?', 'problem', 'problem_of_day', NULL, '4 m/s²', 'F = ma, a = F/m = 8/2 = 4 m/s²', 'easy', 5, 120),
('nsmq_phy_pod_013', 'subj_physics', 'An object floats in water with 3/4 of its volume submerged. What is its density?', 'problem', 'problem_of_day', NULL, '750 kg/m³', 'Fraction submerged = ρ_object/ρ_water. 3/4 = ρ/1000, ρ = 750 kg/m³', 'hard', 5, 120),
('nsmq_phy_pod_014', 'subj_physics', 'A lens forms an image 3 times the size of the object. If the object is 10 cm from the lens, find the focal length.', 'problem', 'problem_of_day', NULL, '7.5 cm', 'm = v/u = 3, v = 30 cm. 1/f = 1/30 + 1/10 = 4/30, f = 7.5 cm', 'hard', 5, 120),
('nsmq_phy_pod_015', 'subj_physics', 'How much heat is needed to raise the temperature of 2 kg of water by 25°C? (c = 4200 J/kg°C)', 'problem', 'problem_of_day', NULL, '210,000 J', 'Q = mcΔT = 2 × 4200 × 25 = 210,000 J', 'medium', 5, 120),
('nsmq_phy_pod_016', 'subj_physics', 'A capacitor of 5μF is charged to 100V. How much charge does it store?', 'problem', 'problem_of_day', NULL, '500 μC', 'Q = CV = 5 × 10⁻⁶ × 100 = 5 × 10⁻⁴ C = 500 μC', 'medium', 5, 120),
('nsmq_phy_pod_017', 'subj_physics', 'A bullet of mass 20g moving at 400 m/s is brought to rest in 0.04 s. What is the average force?', 'problem', 'problem_of_day', NULL, '200 N', 'F = ma = m(Δv/Δt) = 0.02 × 400/0.04 = 200 N', 'hard', 5, 120),
('nsmq_phy_pod_018', 'subj_physics', 'What is the electric field strength at a point where a charge of 2C experiences a force of 10N?', 'problem', 'problem_of_day', NULL, '5 N/C', 'E = F/q = 10/2 = 5 N/C', 'medium', 5, 120),
('nsmq_phy_pod_019', 'subj_physics', 'A pendulum has length 1 m. What is its period? (g = 10 m/s², π = 3.14)', 'problem', 'problem_of_day', NULL, '2 s', 'T = 2π√(L/g) = 2 × 3.14 × √(1/10) ≈ 2 s', 'medium', 5, 120),
('nsmq_phy_pod_020', 'subj_physics', 'A 12V battery is connected to a circuit with total resistance 4Ω. What current flows?', 'problem', 'problem_of_day', NULL, '3 A', 'I = V/R = 12/4 = 3 A', 'easy', 5, 120),

