('nsmq_chem_pod_001', 'subj_chemistry', 'Calculate the number of moles in 11 g of CO₂. (C=12, O=16)', 'problem', 'problem_of_day', NULL, '0.25 mol', 'Molar mass CO₂ = 44 g/mol. Moles = 11/44 = 0.25 mol', 'medium', 5, 120),
