('nsmq_chem_pod_004', 'subj_chemistry', 'How many atoms are in 2 moles of water molecules?', 'problem', 'problem_of_day', NULL, '3.612 × 10²⁴', '2 mol × 3 atoms × 6.02 × 10²³ = 3.612 × 10²⁴ atoms', 'medium', 5, 120),
