('nsmq_chem_pod_007', 'subj_chemistry', 'What mass of NaOH is needed to neutralize 100 mL of 0.5M HCl? (Na=23, O=16, H=1)', 'problem', 'problem_of_day', NULL, '2 g', 'Moles HCl = 0.1 × 0.5 = 0.05. Mass NaOH = 0.05 × 40 = 2 g', 'hard', 5, 120),
('nsmq_chem_pod_008', 'subj_chemistry', 'A hydrocarbon contains 80% carbon by mass. If its molar mass is 30 g/mol, find its molecular formula.', 'problem', 'problem_of_day', NULL, 'C₂H₆', 'C: 24g (2 atoms), H: 6g (6 atoms). Formula: C₂H₆ (ethane)', 'hard', 5, 120),
