('nsmq_chem_pod_010', 'subj_chemistry', 'Calculate the molarity of a solution containing 4 g of NaOH in 500 mL. (Na=23, O=16, H=1)', 'problem', 'problem_of_day', NULL, '0.2 M', 'Moles = 4/40 = 0.1. M = 0.1/0.5 = 0.2 M', 'medium', 5, 120),
('nsmq_chem_pod_011', 'subj_chemistry', 'How many grams of CaCO₃ decompose to produce 5.6 L of CO₂ at STP? (Ca=40, C=12, O=16)', 'problem', 'problem_of_day', NULL, '25 g', 'Moles CO₂ = 5.6/22.4 = 0.25. Mass CaCO₃ = 0.25 × 100 = 25 g', 'hard', 5, 120),
('nsmq_chem_pod_012', 'subj_chemistry', 'What is the empirical formula of a compound with 40% C, 6.67% H, and 53.33% O?', 'problem', 'problem_of_day', NULL, 'CH₂O', 'C: 40/12=3.33, H: 6.67/1=6.67, O: 53.33/16=3.33. Ratio 1:2:1 = CH₂O', 'hard', 5, 120),
('nsmq_chem_pod_013', 'subj_chemistry', 'Calculate the number of electrons in SO₄²⁻ ion. (S=16, O=8)', 'problem', 'problem_of_day', NULL, '50', 'S: 16, O: 4×8=32, +2 for charge = 50 electrons', 'medium', 5, 120),
('nsmq_chem_pod_014', 'subj_chemistry', 'What mass of oxygen is needed to completely burn 16 g of methane? (C=12, H=1, O=16)', 'problem', 'problem_of_day', NULL, '64 g', 'CH₄ + 2O₂ → CO₂ + 2H₂O. Moles CH₄ = 1. Moles O₂ = 2. Mass = 64 g', 'hard', 5, 120),
('nsmq_chem_pod_015', 'subj_chemistry', 'What is the concentration of OH⁻ in a solution with pH = 11?', 'problem', 'problem_of_day', NULL, '10⁻³ M', 'pOH = 14 - 11 = 3. [OH⁻] = 10⁻³ M', 'medium', 5, 120),
('nsmq_chem_pod_016', 'subj_chemistry', 'A reaction has ΔH = -100 kJ and ΔS = -50 J/K. At what temperature is ΔG = 0?', 'problem', 'problem_of_day', NULL, '2000 K', 'ΔG = ΔH - TΔS = 0. T = ΔH/ΔS = 100000/50 = 2000 K', 'hard', 5, 120),
('nsmq_chem_pod_017', 'subj_chemistry', 'What is the mass of 1 mole of electrons? (mass of 1 electron = 9.1 × 10⁻³¹ kg)', 'problem', 'problem_of_day', NULL, '5.48 × 10⁻⁷ kg', 'Mass = 6.02 × 10²³ × 9.1 × 10⁻³¹ = 5.48 × 10⁻⁷ kg', 'hard', 5, 120),
('nsmq_chem_pod_018', 'subj_chemistry', 'Calculate the entropy change when 1 mole of ice melts at 273 K. (ΔH_fusion = 6 kJ/mol)', 'problem', 'problem_of_day', NULL, '22 J/K', 'ΔS = ΔH/T = 6000/273 ≈ 22 J/K', 'hard', 5, 120),
('nsmq_chem_pod_019', 'subj_chemistry', 'How many isomers does C₄H₁₀ have?', 'problem', 'problem_of_day', NULL, '2', 'n-butane and isobutane (2-methylpropane)', 'medium', 5, 120),
