('nsmq_bio_pod_008', 'subj_biology', 'A man with blood type A (heterozygous) marries a woman with blood type B (heterozygous). What is the probability of their child having blood type O?', 'problem', 'problem_of_day', NULL, '25%', 'IAi × IBi. Offspring: IAIB, IAi, IBi, ii. Type O (ii) = 1/4 = 25%', 'hard', 5, 120),
('nsmq_bio_pod_009', 'subj_biology', 'If a food chain has 1000 kcal at the producer level, how much energy is available to the tertiary consumer?', 'problem', 'problem_of_day', NULL, '1 kcal', '10% rule: 1000 → 100 → 10 → 1 kcal', 'medium', 5, 120),
('nsmq_bio_pod_010', 'subj_biology', 'A cell undergoes 5 rounds of mitosis. How many cells result?', 'problem', 'problem_of_day', NULL, '32', '2⁵ = 32 cells', 'easy', 5, 120),
('nsmq_bio_pod_011', 'subj_biology', 'If the DNA template strand is 3''-TACGGT-5'', what is the mRNA sequence?', 'problem', 'problem_of_day', NULL, '5''-AUGCCA-3''', 'mRNA is complementary to template: A→U, T→A, C→G, G→C', 'medium', 5, 120),
('nsmq_bio_pod_012', 'subj_biology', 'Calculate the water potential if solute potential is -0.5 MPa and pressure potential is 0.3 MPa.', 'problem', 'problem_of_day', NULL, '-0.2 MPa', 'Ψ = Ψs + Ψp = -0.5 + 0.3 = -0.2 MPa', 'hard', 5, 120),
('nsmq_bio_pod_013', 'subj_biology', 'In a dihybrid cross (AaBb × AaBb), what fraction of offspring will be heterozygous for both traits?', 'problem', 'problem_of_day', NULL, '4/16 or 1/4', 'AaBb appears 4 times in 16 possible combinations = 4/16 = 1/4', 'hard', 5, 120),
('nsmq_bio_pod_014', 'subj_biology', 'If a person breathes 15 times per minute with a tidal volume of 500 mL, what is the minute ventilation?', 'problem', 'problem_of_day', NULL, '7.5 L/min', 'MV = RR × TV = 15 × 0.5 = 7.5 L/min', 'medium', 5, 120),
('nsmq_bio_pod_015', 'subj_biology', 'A colorblind man (XᶜY) marries a carrier woman (XᶜX). What percentage of sons will be colorblind?', 'problem', 'problem_of_day', NULL, '50%', 'Sons: XᶜY or XY. 50% will be colorblind (XᶜY)', 'medium', 5, 120),
('nsmq_bio_pod_016', 'subj_biology', 'If the rate of transpiration is 2 mL/min and leaf surface area is 100 cm², what is the transpiration rate per unit area?', 'problem', 'problem_of_day', NULL, '0.02 mL/min/cm²', 'Rate = 2/100 = 0.02 mL/min/cm²', 'medium', 5, 120),
('nsmq_bio_pod_017', 'subj_biology', 'Calculate the magnification if the eyepiece is 10× and objective lens is 40×.', 'problem', 'problem_of_day', NULL, '400×', 'Total magnification = eyepiece × objective = 10 × 40 = 400×', 'easy', 5, 120),
('nsmq_bio_pod_018', 'subj_biology', 'If 6CO₂ are used in photosynthesis, how many O₂ molecules are produced?', 'problem', 'problem_of_day', NULL, '6', '6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂', 'easy', 5, 120),
